import React, { createContext } from "react";
import { useParams } from "react-router-dom";
import * as Sentry from "@sentry/react";
import { getFunctions, httpsCallable } from "firebase/functions";
import { getDatabase, ref, update, onValue } from "firebase/database";

import { getAuth, onAuthStateChanged } from "../auth";
import firebase from "../firebase";
import FormClassTemplate from "../components/Pages/FormClassTemplate";

export const UserContext = createContext({ user: null, authIsLoading: false });

// admins/reviewers are comma-separated email lists. Match a whole entry, ignoring case and
// spaces, the same way database.rules.json does.
export const isListedEmail = (list, email) =>
  Boolean(email) &&
  String(list ?? "")
    .split(",")
    .map((e) => e.trim().toLowerCase())
    .includes(email.toLowerCase());

class UserProviderClass extends FormClassTemplate {
  constructor(props) {
    super(props);
    this.state = {
      user: null,
      authIsLoading: false,
      admins: [],
      reviewers: [],
      isReviewer: false,
      loggedIn: false,
      hasSharedRecords: false,
      dataciteApiDomain: "production",
      doiSuffixModes: ["default"],
      doiStatusManagement: "datacite",
    };
  }

  componentDidMount = () => {
    const { region } = this.props;

    this.setState({ authIsLoading: true });
    this.unsubscribe = onAuthStateChanged(getAuth(firebase), (userAuth) => {
      if (userAuth) {
        const { displayName, email, uid } = userAuth;
        this.setState({ user: userAuth, authIsLoading: false, loggedIn: true });

        Sentry.setUser({
          email,
          username: email,
        });

        // should be replaced with getDatacitePrefix but can't as this function is not async
        const functions = getFunctions();
        const getDatacitePrefix = httpsCallable(functions, "getDatacitePrefix");
        getDatacitePrefix(region).then((prefix) => {
          this.setState({
            datacitePrefix: prefix?.data,
          });
        });

        const database = getDatabase(firebase);
        update(ref(database, `${region}/users/${uid}/userinfo`), {
          displayName,
          email,
        });

        const permissionsRef = ref(database, `admin/${region}/permissions`);
        const dataciteCredentialsRef = ref(
          database,
          `admin/${region}/dataciteCredentials`,
        );

        onValue(dataciteCredentialsRef, (snapshot) => {
          const data = snapshot.val();
          this.setState({
            dataciteApiDomain: data?.apiDomain || "production",
            doiSuffixModes:
              Array.isArray(data?.doiSuffixModes) &&
              data.doiSuffixModes.length > 0
                ? data.doiSuffixModes
                : ["default"],
            doiStatusManagement: data?.doiStatusManagement || "datacite",
          });
        });

        this.listenerRefs.push(dataciteCredentialsRef);

        onValue(permissionsRef, (permissionsFB) => {
          const permissions = permissionsFB.toJSON();

          const admins = permissions?.admins || "";
          const reviewers = permissions?.reviewers || "";

          const isAdmin = isListedEmail(admins, email);
          const isReviewer = isListedEmail(reviewers, email);

          this.setState({
            admins,
            reviewers,
            isAdmin,
            isReviewer,
          });
        });

        this.listenerRefs.push(permissionsRef);

        // real-time listener for shared records
        const sharesRef = ref(database, `${region}/shares/${uid}`);

        onValue(sharesRef, (snapshot) => {
          const hasSharedRecords = snapshot.exists();
          this.setState({ hasSharedRecords, authIsLoading: false });
        });

        this.listenerRefs.push(sharesRef);
      } else {
        this.setState({
          loggedIn: false,
          authIsLoading: false,
        });
      }
      this.setState({ user: userAuth, authIsLoading: false });
    });
  };

  render() {
    const { children } = this.props;
    const functions = getFunctions();
    const translate = httpsCallable(functions, "translate");
    const regenerateXMLforRecord = httpsCallable(
      functions,
      "regenerateXMLforRecord",
    );
    const downloadRecord = httpsCallable(functions, "downloadRecord");
    const createDraftDoi = httpsCallable(functions, "createDraftDoi");
    const updateDraftDoi = httpsCallable(functions, "updateDraftDoi");
    const deleteDraftDoi = httpsCallable(functions, "deleteDraftDoi");
    const getDoiStatus = httpsCallable(functions, "getDoiStatus");
    const checkURLActive = httpsCallable(functions, "checkURLActive");
    const getCredentialsStored = httpsCallable(
      functions,
      "getCredentialsStored",
    );
    const getDatacitePrefix = httpsCallable(functions, "getDatacitePrefix");
    const testDataciteCredentials = httpsCallable(
      functions,
      "testDataciteCredentials",
    );
    const publishDoi = httpsCallable(functions, "publishDoi");
    const registerDoi = httpsCallable(functions, "registerDoi");
    const hideDoi = httpsCallable(functions, "hideDoi");
    const publishRecordToGitHub = httpsCallable(
      functions,
      "githubPublishRecord",
    );
    const shareRecord = httpsCallable(functions, "shareRecord");
    const unshareRecord = httpsCallable(functions, "unshareRecord");
    const transferRecord = httpsCallable(functions, "transferRecord");
    // Automated review (reviewer-functions/review.py); URL + LLM checks take a while.
    const reviewRecord = httpsCallable(functions, "review_record", {
      timeout: 540000,
    });
    // Progress is read from {region}/qaRuns, so callers needn't await the whole run.
    const reviewRegion = httpsCallable(functions, "review_region", {
      timeout: 3600000,
    });

    return (
      <UserContext.Provider
        value={{
          ...this.state,
          translate,
          regenerateXMLforRecord,
          downloadRecord,
          createDraftDoi,
          updateDraftDoi,
          deleteDraftDoi,
          getDoiStatus,
          checkURLActive,
          getCredentialsStored,
          getDatacitePrefix,
          testDataciteCredentials,
          publishDoi,
          registerDoi,
          hideDoi,
          publishRecordToGitHub,
          shareRecord,
          unshareRecord,
          transferRecord,
          reviewRecord,
          reviewRegion,
        }}
      >
        {children}
      </UserContext.Provider>
    );
  }
}

// Wrapper component to provide router params to the class component
const UserProvider = ({ children }) => {
  const { region } = useParams();
  return <UserProviderClass region={region}>{children}</UserProviderClass>;
};

export default UserProvider;
